(async()=>{
'use strict';const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let data,current,mode='path',selected=0;
try{const res=await fetch('rag-observatory.json');if(!res.ok)throw Error(res.status);data=await res.json();}catch(e){$('#question').textContent='자료를 읽지 못했습니다. 로컬 데모 서버로 실행하세요.';return;}
const st=data.stats;$('#metrics').innerHTML=[['검토 공고',51,'기존 표본'],['색인 문서',st.documents,'기존 파일럿 전체'],['색인 청크',st.chunks,'L1 / L2 / L3 전체'],['생성 답변',st.generated,'300문항 중 실제 생성'],['정상 권한 차단',st.denied,'LLM 미호출 · 기존 기록']].map(([a,b,c])=>`<div class="metric"><small>${a}</small><b>${Number(b).toLocaleString()}</b><em>${c}</em></div>`).join('');
$('#levels').innerHTML=['L1','L2','L3'].map(l=>`<div class="level"><span>${l} · ${l==='L1'?'공개':l==='L2'?'내부':'민감'}</span><b>${st.security_documents[l]} 문서</b></div>`).join('');$('#case').innerHTML=data.cases.map((r,i)=>`<option value="${i}">${i+1}. ${esc(r.question)}</option>`).join('');
function evidence(i){selected=i;const c=current.contexts[i];$('#evidence').innerHTML=`<span class="badge">${c.scope==='prompt_context'?'생성 시 입력 ['+c.citation+']':'사후 추가 검수 · 입력에 없었음'}</span><h3>${esc(c.filename)}</h3><code>${esc(c.chunk_id)}</code><p class="muted">L1 · 정본 문자 [${c.text_start}, ${c.text_end})<br>Unicode · 0부터 시작 · 끝 제외</p><pre>${esc(c.text)}</pre>`;graph();}
function citations(t){return esc(t).replace(/\[(\d+)\]/g,(m,n)=>current.contexts.some(c=>c.citation===Number(n))?`<button class="citation" data-citation="${n}" aria-label="인용 ${n} 근거 보기">[${n}]</button>`:`<span title="입력에 없는 번호">${m}</span>`);}
function answer(){let out='';const ch=Array.from(current.answer);if(!$('#highlights').checked)out=citations(current.answer);else{const bs=[...new Set([0,ch.length,...current.spans.flatMap(s=>[s.start,s.end])])].sort((a,b)=>a-b);for(let i=0;i<bs.length-1;i++){const a=bs[i],b=bs[i+1],ss=current.spans.filter(s=>s.start<=a&&s.end>=b),t=citations(ch.slice(a,b).join(''));out+=ss.length?`<mark data-label="${esc(ss[0].label)}" title="${esc(ss.map(s=>s.label+': '+s.reason).join(' / '))}">${t}</mark>`:t;}}$('#answer').innerHTML=out;$('#quality').innerHTML=current.quality_notes.map(t=>'<p>검수 메모 · '+esc(t)+'</p>').join('');}
function node(x,y,r,c,label,id){return `<g class="node" data-node="${esc(id)}" tabindex="0" role="button" aria-label="${esc(label||id)}"><rect x="${x-12}" y="${y-16}" width="${label?125:26}" height="32" fill="transparent" pointer-events="all"/><circle cx="${x}" cy="${y}" r="${r+7}" fill="${c}" opacity=".08"/><circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/><text x="${x+16}" y="${y+4}" fill="#cedbed" font-size="11">${esc(label)}</text></g>`;}
function edge(x,y,a,b,on=false){return `<path class="edge ${on?'active':''}" d="M${x},${y} C${(x+a)/2},${y} ${(x+a)/2},${b} ${a},${b}"/>`;}
function graph(){let es='',ns='';if(mode==='tree'){const gs=new Map();for(const d of data.public_documents){if(!gs.has(d.bid_key))gs.set(d.bid_key,[]);gs.get(d.bid_key).push(d);}let k=0;for(const [bid,ds] of gs){const y=28+k*10.3,x=340+Math.sin(k*.9)*45;es+=edge(120,290,x,y);ns+=node(x,y,3,'#58dbcf',k%7===0?bid:'',`bid:${bid}`);ds.forEach((d,j)=>{const dx=610+j*38,dy=y+(j-(ds.length-1)/2)*4;es+=edge(x,y,dx,dy);ns+=node(dx,dy,3,'#aa98f4','',`doc:${d.document_id}`);});k++;}ns+=node(120,290,12,'#58dbcf','공개 공고','root');$('#graph-caption').textContent=`${gs.size}개 공고 → ${data.public_documents.length}개 공개 문서 · 노드를 선택하세요.`;}else{const ds=[...new Set(current.contexts.map(c=>c.document_id))];ds.forEach((d,j)=>{const y=140+j*125;es+=edge(65,280,235,y);ns+=node(235,y,9,'#58dbcf',`문서 ${j+1}`,`document:${d}`);});current.contexts.forEach((c,i)=>{const y=110+i*125,dy=140+ds.indexOf(c.document_id)*125,extra=c.scope!=='prompt_context';es+=edge(235,dy,475,y,selected===i);if(!extra)es+=edge(475,y,720,280,selected===i);ns+=node(475,y,10,extra?'#8998ac':'#aa98f4',extra?'추가 검수':`입력 [${c.citation}]`,`context:${i}`);});ns+=node(65,280,12,'#58dbcf','공고','root')+node(720,280,14,'#f1c27b','답변','answer');es+=edge(720,280,720,465);ns+=node(720,465,9,'#f1c27b','검수 대기','review');$('#graph-caption').textContent='문서 → 입력 청크 → 실제 답변 · 사후 추가 근거는 답변 입력에 연결하지 않습니다.';}$('#network').innerHTML=es+ns;document.querySelector('.legend').innerHTML=mode==='tree'?'<span>● 공개 공고</span><span>● 공개 문서</span>':'<span>● 공고·문서</span><span>● 입력 청크</span><span>● 답변·검수</span>';}
function choose(){current=data.cases[Number($('#case').value)];$('#question').textContent=current.question;$('#notice-link').href='public-notices.html?bid='+encodeURIComponent(current.bid);answer();evidence(0);}
function setMode(m){mode=m;$('#path-mode').setAttribute('aria-pressed',String(m==='path'));$('#tree-mode').setAttribute('aria-pressed',String(m==='tree'));graph();}
$('#case').onchange=choose;$('#highlights').onchange=answer;$('#path-mode').onclick=()=>setMode('path');$('#tree-mode').onclick=()=>setMode('tree');$('#answer').onclick=e=>{const n=e.target.closest('[data-citation]');if(n){setMode('path');evidence(current.contexts.findIndex(c=>c.citation===Number(n.dataset.citation)));}};
function pick(e){const g=e.target.closest('[data-node]');if(!g)return;const id=g.dataset.node;if(id.startsWith('context:'))evidence(Number(id.split(':')[1]));else if(id.startsWith('document:'))evidence(current.contexts.findIndex(c=>c.document_id===id.slice(9)));else if(id.startsWith('doc:')){const d=data.public_documents.find(d=>d.document_id===id.slice(4));$('#evidence').innerHTML=`<span class="badge">L1 문서 메타데이터</span><h3>${esc(d.filename)}</h3><code>${esc(d.document_id)}</code><p>색인 청크 ${d.chunks}개</p><p class="muted">전체 원문은 이 화면에 포함하지 않았습니다. 저장 답변을 선택하면 해당 근거 구간을 볼 수 있습니다.</p>`;}else if(id==='answer')$('#answer').scrollIntoView({block:'center'});else if(id.startsWith('bid:'))$('#evidence').innerHTML='<h3>'+esc(id.slice(4))+'</h3><a href="public-notices.html?bid='+encodeURIComponent(id.slice(4))+'">공고와 요건 보기 ↗</a>';}
$('#network').onclick=pick;$('#network').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick(e);}};choose();
})();